(function () {
  if (window.__foldLowSubstance) return;
  window.__foldLowSubstance = true;

  const SEL = 'article[data-post-id]';
  const seen = new Set();

  const style = document.createElement('style');
  style.textContent = `
    .wk-fold-stub { font-size: 13px; color: #666; padding: 6px 10px; border-left: 3px solid #ccc; margin: 6px 0; }
    .wk-fold-stub button { margin-left: 8px; font-size: 12px; }
    .wk-fold-hidden { display: none !important; }
  `;
  document.head.appendChild(style);

  function fold(article, reason) {
    if (article.dataset.wkFolded) return;
    article.dataset.wkFolded = '1';
    const body = article.querySelector('.topic-body') || article;
    const stub = document.createElement('div');
    stub.className = 'wk-fold-stub';
    stub.textContent = 'Folded low-substance reply' + (reason ? ' (' + reason + ')' : '');
    const btn = document.createElement('button');
    btn.textContent = 'Show';
    btn.addEventListener('click', () => {
      const showing = body.classList.toggle('wk-fold-hidden') === false;
      btn.textContent = showing ? 'Show' : 'Hide';
    });
    body.classList.add('wk-fold-hidden');
    stub.appendChild(btn);
    article.insertBefore(stub, body);
  }

  async function run() {
    const articles = [...document.querySelectorAll(SEL)].filter((a) => {
      const num = a.dataset.postNumber || a.id;
      if (a.dataset.wkChecked) return false;
      if (a.id === 'post_1' || a.dataset.postNumber === '1') return false;
      return true;
    });
    if (!articles.length) return;
    const items = articles.map((a) => ({
      id: a.dataset.postId,
      text: (a.querySelector('.cooked')?.innerText || '').trim().slice(0, 800),
    })).filter((i) => i.text);
    articles.forEach((a) => a.dataset.wkChecked = a.dataset.wkChecked || '');
    if (!items.length) return;
    try {
      const res = await GM_ai.map(
        items,
        'For each forum reply, answer true if it has substance (adds technical detail, a question, a result, a fix, or a measurement), false if it is only praise, agreement, "+1", thanks, or filler. Answer as JSON object mapping id to boolean.',
        { type: 'boolean' }
      );
      for (const a of articles) {
        const v = res && res[a.dataset.postId];
        if (typeof v !== 'boolean') continue;
        a.dataset.wkChecked = '1';
        if (v === false) fold(a, 'no substance');
      }
    } catch (e) {
      /* leave posts alone if the model is unavailable */
    }
  }

  let timer = null;
  const observer = new MutationObserver(() => {
    clearTimeout(timer);
    timer = setTimeout(run, 500);
  });
  observer.observe(document.body, { childList: true, subtree: true });
  setTimeout(run, 500);
})();

